def pair_exists(nums, target):
    i = 0
    j = len(nums) - 1
    while i < j:
        s = nums[i] + nums[j]
        if s == target:
            return True
        if s < target:
            i += 1
        else:
            j -= 1
    return False


def main():
    nums = list(map(int, input().split()))
    target = int(input())
    print(pair_exists(nums, target))


main()

def max_window_sum(nums, k):
    total = 0
    for i in range(k):
        total += nums[i]
    best = total
    for i in range(k, len(nums)):
        total += nums[i] - nums[i - k]
        if total > best:
            best = total
    return best


def main():
    nums = list(map(int, input().split()))
    k = int(input())
    print(max_window_sum(nums, k))


main()

def range_sum(nums, l, r):
    total = 0
    for i in range(l, r + 1):
        total += nums[i]
    return total


def main():
    nums = list(map(int, input().split()))
    l, r = map(int, input().split())
    print(range_sum(nums, l, r))


main()

