def count_bits(n):
    count = 0
    while n > 0:
        count += n & 1
        n >>= 1
    return count


def main():
    n = int(input())
    print(count_bits(n))


main()

def best_streak(days):
    cur = days[0]
    best = days[0]
    for x in days[1:]:
        if cur > 0:
            cur += x
        else:
            cur = x
        if cur > best:
            best = cur
    return best


def main():
    days = list(map(int, input().split()))
    print(best_streak(days))


main()

def favourite(votes):
    counts = {}
    for v in votes:
        counts[v] = counts.get(v, 0) + 1
    for v in counts:
        if counts[v] * 2 > len(votes):
            return v
    return -1


def main():
    votes = list(map(int, input().split()))
    print(favourite(votes))


main()

def best_profit(prices):
    best = -1
    lowest = prices[0]
    for x in prices[1:]:
        d = x - lowest
        if d > best:
            best = d
        if x < lowest:
            lowest = x
    if best <= 0:
        return -1
    return best


def main():
    prices = list(map(int, input().split()))
    print(best_profit(prices))


main()

def colour_census(nums):
    zeros = 0
    ones = 0
    twos = 0
    for x in nums:
        if x == 0:
            zeros += 1
        elif x == 1:
            ones += 1
        else:
            twos += 1
    return (zeros, ones, twos)


def main():
    nums = list(map(int, input().split()))
    zeros, ones, twos = colour_census(nums)
    print(zeros, ones, twos)


main()

def closest_pair_sum(nums, target):
    i = 0
    j = len(nums) - 1
    best_d = None
    best_sum = None
    while i < j:
        s = nums[i] + nums[j]
        d = s - target
        if d < 0:
            d = -d
        if best_d is None or d < best_d:
            best_d = d
            best_sum = s
        if s == target:
            break
        if s < target:
            i += 1
        else:
            j -= 1
    return best_sum


def main():
    nums = list(map(int, input().split()))
    target = int(input())
    print(closest_pair_sum(nums, target))


main()

def balance_index(nums):
    total = 0
    for x in nums:
        total += x
    left = 0
    for i in range(len(nums)):
        if left == total - left - nums[i]:
            return i
        left += nums[i]
    return -1


def main():
    nums = list(map(int, input().split()))
    print(balance_index(nums))


main()

