    print(max_subarray(nums))


main()

def majority_element(nums):
    candidate = None
    count = 0
    for x in nums:
        if count == 0:
            candidate = x
            count = 1
        elif x == candidate:
            count += 1
        else:
            count -= 1
    return candidate


def main():
    nums = list(map(int, input().split()))
    print(majority_element(nums))


main()

def max_gain(prices):
    best = -1
    lowest = prices[0]
    for x in prices[1:]:
        d = x - lowest
        if d > best:
            best = d
        if x < lowest:
            lowest = x
    if best <= 0:
        return -1
    return best


def main():
    prices = list(map(int, input().split()))
    print(max_gain(prices))


main()

def dutch_partition(nums):
    low = 0
    mid = 0
    high = len(nums) - 1
    while mid <= high:
        if nums[mid] == 0:
            nums[low], nums[mid] = nums[mid], nums[low]
            low += 1
            mid += 1
        elif nums[mid] == 1:
            mid += 1
        else:
            nums[mid], nums[high] = nums[high], nums[mid]
            high -= 1
    return nums


def main():
    nums = list(map(int, input().split()))
    print(' '.join(map(str, dutch_partition(nums))))


main()
